     */
    function unshield(
        address from,
        address to,
        sharedEuint64 sharedAmount
    ) public virtual nonReentrant returns (sharedEuint64) {
        euint64 amount = FHE.receiveEuint64Param(sharedAmount);
        return FHE.shareEuint64(_unshield(from, to, amount), msg.sender);
